# v13.53: shared-bill editor (one row, merchant+branch, split modes), one person once, pickers, placeholder, real coin logos
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'; res=[]
def ok(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block'); pg=ctx.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached')
    pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(900)
    J=lambda js: pg.evaluate("(async()=>{const c=await import('/js/core.js');"+js+"})()")
    J("c.commit(d=>{d.settings.mode='advanced';const home=d.settings.homeCur||'PHP';d.accounts.push(c.stamp({id:'w1',name:'Wallet One',cur:home,type:'cash',open:5000,include:true,archived:false}));for(const [i,n] of [['pa','Ana'],['pb','Ben']])d.accounts.push(c.stamp({id:i,name:n,cur:home,type:'owed',open:0,include:true,archived:false}))})")
    J("c.commit(d=>{d.txs.push(c.stamp({id:'m1',kind:'expense',date:'2026-10-01',name:'Old',amount:50,cur:d.accounts.find(a=>a.id==='w1').cur,fx:1,acct:'w1',merchant:'Life',branch:'Tsukagoshi'}))})")
    pg.evaluate("document.querySelector('[data-act=add]').click()"); pg.wait_for_selector('#entry'); pg.wait_for_timeout(400)
    ok('placeholder is e.g. Grab, Matcha, Cheesecake', 'Grab, Matcha, Cheesecake' in pg.get_attribute('#f-what','placeholder'))
    pg.fill('#f-what','Team Dinner'); pg.evaluate("(()=>{const e=document.querySelector('#f-acct');e.value='w1';e.dispatchEvent(new Event('change',{bubbles:true}))})()"); pg.fill('#f-amount','900'); pg.wait_for_timeout(300)
    # merchant picker rows are centred and readable
    pg.evaluate("document.querySelector('[data-e=merchpick]').click()"); pg.wait_for_selector('.mpr'); pg.wait_for_timeout(300)
    ta=pg.evaluate("getComputedStyle(document.querySelector('.mpr .rmain strong')).justifyContent"); wr=pg.evaluate("Math.round(document.querySelector('.mpr').getBoundingClientRect().width)")
    ok('merchant rows are full width and left aligned (%s, %s)'%(ta,wr), ta in ('flex-start','start') and wr>300)
    pg.evaluate("document.querySelector('.mpr[data-m=Life]').click()"); pg.wait_for_timeout(400)
    pg.evaluate("document.querySelector('#branchcell [data-e=branchpick]').click()"); pg.wait_for_selector('[data-b]'); pg.wait_for_timeout(300)
    hh=pg.evaluate("Math.round(document.querySelector('[data-b=\"\"]').getBoundingClientRect().height)"); ok('No branch is a one-line row (%s px)'%hh, hh<=64)
    pg.evaluate("document.querySelector('[data-b=Tsukagoshi]').click()"); pg.wait_for_timeout(300)
    # paid for others: choosing the same person again removes the earlier line
    pg.evaluate("document.querySelector('[data-e=oth-on]').click()"); pg.wait_for_timeout(300); pg.evaluate("document.querySelector('[data-e=oth-add]').click()"); pg.wait_for_timeout(200)
    pg.locator('.oth-who').nth(0).select_option('pa'); pg.wait_for_timeout(400)
    o2=pg.evaluate("[...document.querySelectorAll('.oth-who')[1].options].map(o=>o.value)")
    ok('a person already chosen is not offered again %s'%o2, 'pa' not in o2 and 'pb' in o2)
    pg.evaluate("document.querySelector('[data-e=oth-add]').click()"); pg.wait_for_timeout(200); pg.locator('.oth-who').nth(1).select_option('pb'); pg.wait_for_timeout(300)
    pg.evaluate("document.querySelector('#btns [data-e=save]').click()"); pg.wait_for_timeout(1200)
    parts=J("return c.get().txs.filter(t=>!t.deleted&&t.splitId).map(t=>[t.kind,t.merchant,t.branch])")
    parts=pg.evaluate("(async()=>{const c=await import('/js/core.js');return c.get().txs.filter(t=>!t.deleted&&t.splitId).map(t=>[t.kind,t.merchant||'',t.branch||''])})()")
    ok('merchant and branch saved on every part %s'%parts, len(parts)==3 and all(x[1]=='Life' and x[2]=='Tsukagoshi' for x in parts))
    lent=pg.evaluate("(async()=>{const c=await import('/js/core.js');return c.get().txs.find(t=>!t.deleted&&t.lent&&t.splitId).id})()")
    pg.evaluate("(async()=>{const s=await import('/js/splitbill.js');s.openSplit('%s')})()"%lent); pg.wait_for_selector('[data-sb=total]'); pg.wait_for_timeout(300)
    r=pg.evaluate("(()=>{const a=document.querySelector('[data-sb=total]').getBoundingClientRect(),b=document.querySelector('[data-sb=acct]').getBoundingClientRect();return [Math.round(a.top),Math.round(b.top)]})()")
    ok('Whole Bill and Paid From share one row %s'%r, abs(r[0]-r[1])<6)
    ok('editor shows the merchant and branch from the entry', pg.input_value('[data-sb=merchant]')=='Life' and pg.input_value('[data-sb=branch]')=='Tsukagoshi')
    # modes
    pg.evaluate("document.querySelector('[data-sb=mode][data-v=equal]').click()"); pg.wait_for_timeout(200)
    ok('Split Equally: 900 / 3 = 300 each', pg.locator('.sbfixed').count()==2 and all('300' in x for x in pg.locator('.sbfixed').all_inner_texts()))
    pg.evaluate("document.querySelector('[data-sb=mode][data-v=pct]').click()"); pg.wait_for_timeout(200)
    pg.evaluate("(()=>{const e=document.querySelector('[data-sb=pct][data-i=\"0\"]');e.value='50';e.dispatchEvent(new Event('change',{bubbles:true}))})()"); pg.wait_for_timeout(200)
    ok('Percentages: 50% of 900 = 450', '450' in pg.inner_text('#sb'))
    pg.evaluate("document.querySelector('[data-sb=mode][data-v=amount]').click()"); pg.wait_for_timeout(200)
    ok('Set Each Amount inputs back', pg.locator('[data-sb=share]').count()==2)
    pg.evaluate("(()=>{const e=document.querySelector('[data-sb=branch]');e.value='kawasaki   station';e.dispatchEvent(new Event('change',{bubbles:true}))})()"); pg.wait_for_timeout(200)
    ok('branch typed is Title Case', pg.input_value('[data-sb=branch]')=='Kawasaki Station')
    # real coin logos
    pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
    pg.evaluate("import('/js/curpicker.js').then(m=>{window.__h=m.coinIcon('BNB')+m.coinIcon('BTC')+m.coinIcon('SOL')})"); pg.wait_for_timeout(300)
    h=pg.evaluate("window.__h"); ok('BNB, BTC, SOL use real logo files, not letters', h.count('<img')==3 and 'vendor/coins/bnb.svg' in h)
    ok('logo files load', pg.evaluate("Promise.all(['bnb','btc','sol','usdt','xrp'].map(c=>fetch('/vendor/coins/'+c+'.svg').then(r=>r.ok)))").count(True)==5 if False else all(pg.evaluate("Promise.all(['bnb','btc','sol','usdt','xrp'].map(c=>fetch('/vendor/coins/'+c+'.svg').then(r=>r.ok)))")))
    ok('no errors %s'%errs[:2], not errs)
    b.close()
print('SUMMARY',sum(res),'passed',len(res)-sum(res),'failed')
